static const struct alias *
aliases_lookup (const char *str, unsigned int len)
{
  unsigned int i;
  for (i = 0; i < sizeof(aliases)/sizeof(aliases[0]); i++)
    {
      const char *name = stringpool + aliases[i].name;
      if (name[len] == '\0' && memcmp(name, str, len) == 0)
        return &aliases[i];
    }
  return NULL;
}
